local BellFounder = {}
local BELLS = {
    hand_bell = { name = "Ročni zvonec", bronzeCost = 1, time = 2, cost = 20, soundQuality = 10, happiness = 1, description = "Majhen ročni zvonec." },
    church_bell = { name = "Cerkevni zvonec", bronzeCost = 8, time = 14, cost = 300, soundQuality = 30, faith = 10, happiness = 3, description = "Veliki cerkevni zvonec." },
    carillon = { name = "Karilon", bronzeCost = 30, time = 60, cost = 2000, soundQuality = 50, faith = 20, happiness = 10, prestige = 15, description = "Niz zvonov za melodije." },
    angelus_bell = { name = "Angel zvonec", bronzeCost = 12, time = 21, cost = 500, soundQuality = 35, faith = 15, happiness = 5, description = "Zvonec za angelus." },
    royal_bell = { name = "Kraljevski zvonec", bronzeCost = 20, goldCost = 2, time = 30, cost = 1000, soundQuality = 45, faith = 15, happiness = 8, prestige = 20, description = "Veliki kraljevski zvonec." },
    warning_bell = { name = "Alarmni zvonec", bronzeCost = 5, ironCost = 2, time = 7, cost = 150, soundQuality = 20, militaryBonus = 5, description = "Za alarm in opozorila." },
}
local BUILDINGS = {
    foundry = { name = "Zvonarna", cost = { gold = 500, wood = 200, stone = 300, iron = 100 }, upkeep = 15, qualityBonus = 10 },
    bell_tower = { name = "Zvonik", cost = { gold = 1500, wood = 300, stone = 800 }, upkeep = 30, qualityBonus = 20, prestigeBonus = 10 },
    tuning_shop = { name = "Urnavalnica", cost = { gold = 1000, wood = 200, stone = 200, iron = 50 }, upkeep = 25, qualityBonus = 25 },
    royal_bell_foundry = { name = "Kraljevska zvonarna", cost = { gold = 5000, wood = 500, stone = 1200, iron = 200 }, upkeep = 100, qualityBonus = 40, prestigeBonus = 25 },
}
BellFounder.bronzeStock = 10; BellFounder.ironStock = 5; BellFounder.goldStock = 3
BellFounder.productStock = {}; BellFounder.buildings = {}; BellFounder.bellFounder = nil; BellFounder.activeCasting = {}; BellFounder.totalBells = 0; BellFounder.dayTimer = 0
function BellFounder.init() BellFounder.bronzeStock=10; BellFounder.ironStock=5; BellFounder.goldStock=3; BellFounder.productStock={}; BellFounder.buildings={}; BellFounder.bellFounder=nil; BellFounder.activeCasting={}; BellFounder.totalBells=0; BellFounder.dayTimer=0; print("[BellFounder] Royal Bell Founder & Campanology System initialized (6 bells, 4 buildings)") end
function BellFounder.hireBellFounder(n,s) s=s or math.random(40,85); local c=400+s*8; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BellFounder.bellFounder={name=n or ("Zvonolivar "..math.random(1,99)),skill=s,hiredDay=os.time(),bellsCast=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zvonolivar najet: %s (spretnost: %d)",BellFounder.bellFounder.name,s),"success") end; return true end
function BellFounder.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BellFounder.build(id) local ok,e=BellFounder.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BellFounder.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BellFounder.getQualityBonus() local b=0; for _,bd in ipairs(BellFounder.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BellFounder.canCast(bt) local d=BELLS[bt]; if not d then return false,"Neznan zvonec" end; if d.bronzeCost and BellFounder.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.ironCost and BellFounder.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.goldCost and BellFounder.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if #BellFounder.buildings==0 then return false,"Potrebna zvonarna" end; if not BellFounder.bellFounder then return false,"Potreben zvonolivar" end; return true end
function BellFounder.cast(bt) local ok,e=BellFounder.canCast(bt); if not ok then return false,e end; local d=BELLS[bt]; if d.bronzeCost then BellFounder.bronzeStock=BellFounder.bronzeStock-d.bronzeCost end; if d.ironCost then BellFounder.ironStock=BellFounder.ironStock-d.ironCost end; if d.goldCost then BellFounder.goldStock=BellFounder.goldStock-d.goldCost end; local t=d.time; if BellFounder.bellFounder then t=math.max(1,t-math.floor(BellFounder.bellFounder.skill/10)) end; table.insert(BellFounder.activeCasting,{id="bell_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),bellType=bt,bellName=d.name,cost=d.cost,soundQuality=d.soundQuality or 0,faith=d.faith or 0,happiness=d.happiness or 0,prestige=d.prestige or 0,militaryBonus=d.militaryBonus or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Livljenje zvona: %s (%d dni)",d.name,t),"info") end; return true end
function BellFounder.completeCasting(c) local failChance=0.10-(BellFounder.bellFounder and BellFounder.bellFounder.skill/500 or 0); failChance=math.max(0.02,failChance); if math.random()<failChance then if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zvon razpokan pri livljenju: %s!",c.bellName),"danger") end; return end; local q=1.0+(BellFounder.getQualityBonus()/100); if BellFounder.bellFounder then q=q+(BellFounder.bellFounder.skill/200) end; q=math.min(2.5,q); BellFounder.productStock[c.bellType]=(BellFounder.productStock[c.bellType] or 0)+1; BellFounder.totalBells=BellFounder.totalBells+1; if _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+c.happiness*q) end; if c.faith>0 and _G.Religion then pcall(_G.Religion.addFaith,c.faith) end; if c.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+c.prestige) end; if BellFounder.bellFounder then BellFounder.bellFounder.bellsCast=BellFounder.bellFounder.bellsCast+1; if math.random()<0.15 then BellFounder.bellFounder.skill=math.min(100,BellFounder.bellFounder.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zvonec ulit: %s (kakovost: %.1f)",c.bellName,q),"success") end end
function BellFounder.update(dt) if not _G.state then return end; BellFounder.dayTimer=BellFounder.dayTimer+dt; if BellFounder.dayTimer>=30 then BellFounder.dayTimer=0; for i=#BellFounder.activeCasting,1,-1 do local c=BellFounder.activeCasting[i]; c.daysRemaining=c.daysRemaining-1; if c.daysRemaining<=0 then BellFounder.completeCasting(c); table.remove(BellFounder.activeCasting,i) end end; local tu=0; for _,bd in ipairs(BellFounder.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BellFounder.bellFounder then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BellFounder.getStats() return {bronzeStock=BellFounder.bronzeStock,ironStock=BellFounder.ironStock,goldStock=BellFounder.goldStock,productStock=BellFounder.productStock,numBuildings=#BellFounder.buildings,hasBellFounder=BellFounder.bellFounder~=nil,bellFounderName=BellFounder.bellFounder and BellFounder.bellFounder.name or "—",bellFounderSkill=BellFounder.bellFounder and BellFounder.bellFounder.skill or 0,activeCasting=#BellFounder.activeCasting,totalBells=BellFounder.totalBells} end
return BellFounder
